CREATE FUNCTION public.app_now() RETURNS timestamp LANGUAGE sql STABLE AS $$ SELECT timezone('Asia/Ulaanbaatar', now()) $$;

CREATE FUNCTION public.app_touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at = public.app_now(); RETURN NEW; END $$;

CREATE TABLE public."leagues" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "tier" int NOT NULL DEFAULT '2',
  "name" varchar(255) NOT NULL,
  "slug" varchar(100) NOT NULL DEFAULT '',
  "description" text,
  "logo" varchar(255) DEFAULT NULL,
  "location" varchar(255) DEFAULT NULL,
  "primary_color" varchar(7) DEFAULT '#E8601C',
  "created_by" int DEFAULT NULL,
  "commissioner_user_id" int DEFAULT NULL,
  "created_at" timestamp without time zone DEFAULT public.app_now()
);

ALTER TABLE public."leagues" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."matches" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "season_id" int NOT NULL,
  "home_season_team_id" int NOT NULL,
  "away_season_team_id" int NOT NULL,
  "match_datetime" timestamp without time zone DEFAULT NULL,
  "stage" varchar(50) DEFAULT NULL,
  "game_no" int DEFAULT NULL,
  "arena_name" varchar(120) DEFAULT NULL,
  "live_embed_code" text,
  "home_score" smallint DEFAULT '0',
  "away_score" smallint DEFAULT '0',
  "status" text DEFAULT 'scheduled' CHECK ("status" IN ('scheduled','live','finished','cancelled', '')),
  "created_by" int DEFAULT NULL,
  "created_at" timestamp without time zone DEFAULT public.app_now(),
  "updated_at" timestamp without time zone DEFAULT public.app_now(),
  "stat_manager_id" int DEFAULT NULL,
  "stat_started_at" timestamp without time zone DEFAULT NULL,
  "stat_submitted_at" timestamp without time zone DEFAULT NULL,
  "stat_status" text DEFAULT NULL CHECK ("stat_status" IN ('in_progress','submitted','approved', '')),
  "boxscore_pdf" varchar(255) DEFAULT NULL
);

CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public."matches" FOR EACH ROW EXECUTE FUNCTION public.app_touch_updated_at();

ALTER TABLE public."matches" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."match_player_stats" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK ("id" >= 0),
  "match_id" int NOT NULL,
  "player_id" int NOT NULL,
  "team_id" int NOT NULL,
  "minutes" int DEFAULT NULL,
  "seconds" int DEFAULT NULL,
  "fg_made" int NOT NULL DEFAULT '0',
  "fg_attempts" int NOT NULL DEFAULT '0',
  "two_made" int NOT NULL DEFAULT '0',
  "two_attempts" int NOT NULL DEFAULT '0',
  "three_made" int NOT NULL DEFAULT '0',
  "three_attempts" int NOT NULL DEFAULT '0',
  "ft_made" int NOT NULL DEFAULT '0',
  "ft_attempts" int NOT NULL DEFAULT '0',
  "reb_off" int NOT NULL DEFAULT '0',
  "reb_def" int NOT NULL DEFAULT '0',
  "reb_total" int NOT NULL DEFAULT '0',
  "assists" int NOT NULL DEFAULT '0',
  "turnovers" int NOT NULL DEFAULT '0',
  "steals" int NOT NULL DEFAULT '0',
  "blocks" int NOT NULL DEFAULT '0',
  "fouls_committed" int NOT NULL DEFAULT '0',
  "fouls_drawn" int NOT NULL DEFAULT '0',
  "plus_minus" int DEFAULT NULL,
  "points" int NOT NULL DEFAULT '0',
  "created_at" timestamp without time zone NULL DEFAULT public.app_now(),
  "updated_at" timestamp without time zone NULL DEFAULT public.app_now(),
  "entered_by" int DEFAULT NULL
);

CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public."match_player_stats" FOR EACH ROW EXECUTE FUNCTION public.app_touch_updated_at();

ALTER TABLE public."match_player_stats" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."match_status" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "match_id" int NOT NULL,
  "period" text NOT NULL CHECK ("period" IN ('Q1','Q2','Q3','Q4','OT', '')),
  "home_score" smallint DEFAULT '0',
  "away_score" smallint DEFAULT '0'
);

ALTER TABLE public."match_status" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."match_submit" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "match_id" int NOT NULL,
  "submitted_by" int DEFAULT NULL,
  "submitted_at" timestamp without time zone DEFAULT public.app_now(),
  "status" text DEFAULT 'submitted' CHECK ("status" IN ('submitted','approved','rejected', '')),
  "user_id" int DEFAULT NULL,
  "approved_by" int DEFAULT NULL,
  "approved_at" timestamp without time zone DEFAULT NULL,
  "note" text
);

ALTER TABLE public."match_submit" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."match_team_stats" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "match_id" int NOT NULL,
  "team_id" int NOT NULL,
  "side" text NOT NULL CHECK ("side" IN ('home','away', '')),
  "points_from_turnovers" smallint DEFAULT '0',
  "points_in_paint" smallint DEFAULT '0',
  "second_chance_points" smallint DEFAULT '0',
  "fast_break_points" smallint DEFAULT '0',
  "bench_points" smallint DEFAULT '0',
  "updated_at" timestamp without time zone DEFAULT public.app_now()
);

CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public."match_team_stats" FOR EACH ROW EXECUTE FUNCTION public.app_touch_updated_at();

ALTER TABLE public."match_team_stats" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."news" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "season_id" int DEFAULT NULL,
  "title" varchar(255) NOT NULL,
  "slug" varchar(255) DEFAULT NULL,
  "excerpt" text,
  "content" text,
  "cover_image" varchar(255) DEFAULT NULL,
  "status" text DEFAULT 'draft' CHECK ("status" IN ('draft','published', '')),
  "created_by" int DEFAULT NULL,
  "approved_by" int DEFAULT NULL,
  "published_at" timestamp without time zone DEFAULT NULL,
  "created_at" timestamp without time zone DEFAULT public.app_now(),
  "updated_at" timestamp without time zone DEFAULT public.app_now()
);

CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public."news" FOR EACH ROW EXECUTE FUNCTION public.app_touch_updated_at();

ALTER TABLE public."news" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."players" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "last_name" varchar(80) NOT NULL,
  "first_name" varchar(80) NOT NULL,
  "birth_date" date DEFAULT NULL,
  "height_cm" smallint DEFAULT NULL,
  "weight_kg" smallint DEFAULT NULL,
  "photo_path" varchar(255) DEFAULT NULL,
  "gender" char(1) DEFAULT 'M',
  "hand" char(1) DEFAULT 'R',
  "phone" varchar(20) DEFAULT NULL,
  "school_name" varchar(100) DEFAULT NULL,
  "created_at" timestamp without time zone DEFAULT public.app_now(),
  "created_by_user_id" int DEFAULT NULL,
  "updated_by_user_id" int DEFAULT NULL,
  "updated_at" timestamp without time zone DEFAULT public.app_now()
);

CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public."players" FOR EACH ROW EXECUTE FUNCTION public.app_touch_updated_at();

ALTER TABLE public."players" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."seasons" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "league_id" int NOT NULL,
  "name" varchar(120) NOT NULL,
  "description" text,
  "start_date" date DEFAULT NULL,
  "end_date" date DEFAULT NULL,
  "status" text DEFAULT 'registration' CHECK ("status" IN ('registration','active','finished', '')),
  "created_id" varchar(100) NOT NULL,
  "created_at" timestamp without time zone DEFAULT public.app_now()
);

ALTER TABLE public."seasons" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."season_teams" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "season_id" int NOT NULL,
  "team_id" int NOT NULL,
  "zone" varchar(50) DEFAULT NULL,
  "seed" smallint DEFAULT NULL,
  "status" text DEFAULT 'active' CHECK ("status" IN ('active','withdrawn', '')),
  "created_at" timestamp without time zone DEFAULT public.app_now()
);

ALTER TABLE public."season_teams" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."stat_manager_assignments" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "match_id" int NOT NULL,
  "user_id" int NOT NULL,
  "assigned_by" int DEFAULT NULL,
  "created_at" timestamp without time zone DEFAULT public.app_now(),
  "rate" decimal(10,2) DEFAULT '0.00',
  "status" text DEFAULT 'assigned' CHECK ("status" IN ('assigned','submitted','approved','rejected','paid', '')),
  "submitted_at" timestamp without time zone DEFAULT NULL,
  "approved_at" timestamp without time zone DEFAULT NULL,
  "approved_by" int DEFAULT NULL,
  "paid_at" timestamp without time zone DEFAULT NULL,
  "paid_by" int DEFAULT NULL,
  "locked_by" int DEFAULT NULL,
  "locked_at" timestamp without time zone DEFAULT NULL
);

ALTER TABLE public."stat_manager_assignments" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."teams" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(120) NOT NULL,
  "logo_path" varchar(255) DEFAULT NULL,
  "city" varchar(80) DEFAULT NULL,
  "short_name" varchar(20) DEFAULT NULL,
  "description" text,
  "gender" text NOT NULL DEFAULT 'M' CHECK ("gender" IN ('M','F','Mixed', '')),
  "primary_color" varchar(7) DEFAULT NULL,
  "created_by_user_id" int DEFAULT NULL,
  "updated_by_user_id" int DEFAULT NULL,
  "created_at" timestamp without time zone DEFAULT public.app_now(),
  "updated_at" timestamp without time zone DEFAULT public.app_now()
);

CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public."teams" FOR EACH ROW EXECUTE FUNCTION public.app_touch_updated_at();

ALTER TABLE public."teams" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."team_season_roster" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "season_team_id" int NOT NULL,
  "team_id" int NOT NULL,
  "player_id" int NOT NULL,
  "jersey_no" varchar(5) DEFAULT NULL,
  "position" varchar(20) DEFAULT NULL,
  "is_captain" smallint DEFAULT '0',
  "status" text DEFAULT 'active' CHECK ("status" IN ('active','inactive','injured', '')),
  "joined_at" date DEFAULT NULL,
  "left_at" date DEFAULT NULL,
  "created_at" timestamp without time zone DEFAULT public.app_now(),
  "updated_at" timestamp without time zone DEFAULT public.app_now()
);

ALTER TABLE public."team_season_roster" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."users" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(120) NOT NULL,
  "email" varchar(120) NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "role" text DEFAULT 'user' CHECK ("role" IN ('admin','commissioner','stat_manager','user', '')),
  "status" text DEFAULT 'active' CHECK ("status" IN ('active','inactive', '')),
  "wallet_balance" decimal(10,2) DEFAULT '0.00',
  "created_at" timestamp without time zone DEFAULT public.app_now(),
  "updated_at" timestamp without time zone DEFAULT public.app_now(),
  "league_id" int DEFAULT NULL
);

CREATE TRIGGER touch_updated_at BEFORE UPDATE ON public."users" FOR EACH ROW EXECUTE FUNCTION public.app_touch_updated_at();

ALTER TABLE public."users" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."wallet_transactions" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "type" text NOT NULL CHECK ("type" IN ('credit','debit', '')),
  "description" varchar(255) DEFAULT NULL,
  "created_at" timestamp without time zone DEFAULT public.app_now(),
  "balance_after" decimal(10,2) DEFAULT '0.00'
);

ALTER TABLE public."wallet_transactions" ENABLE ROW LEVEL SECURITY;

CREATE TABLE public."withdrawal_requests" (
  "id" int GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int NOT NULL,
  "amount" decimal(10,2) NOT NULL,
  "status" text DEFAULT 'pending' CHECK ("status" IN ('pending','approved','rejected', '')),
  "note" text,
  "created_at" timestamp without time zone DEFAULT public.app_now()
);

ALTER TABLE public."withdrawal_requests" ENABLE ROW LEVEL SECURITY;

CREATE UNIQUE INDEX "leagues_slug" ON public."leagues" (LOWER("slug"));

CREATE INDEX "matches_season_id" ON public."matches" ("season_id");

CREATE INDEX "matches_home_season_team_id" ON public."matches" ("home_season_team_id");

CREATE INDEX "matches_away_season_team_id" ON public."matches" ("away_season_team_id");

CREATE UNIQUE INDEX "match_status_uniq_match_period" ON public."match_status" ("match_id","period");

CREATE INDEX "match_status_match_id" ON public."match_status" ("match_id");

CREATE INDEX "match_submit_idx_match" ON public."match_submit" ("match_id");

CREATE UNIQUE INDEX "match_team_stats_uniq_match_side" ON public."match_team_stats" ("match_id","side");

CREATE INDEX "match_team_stats_match_id" ON public."match_team_stats" ("match_id");

CREATE INDEX "seasons_league_id" ON public."seasons" ("league_id");

CREATE UNIQUE INDEX "season_teams_uniq_season_team" ON public."season_teams" ("season_id","team_id");

CREATE INDEX "season_teams_season_id" ON public."season_teams" ("season_id");

CREATE INDEX "season_teams_team_id" ON public."season_teams" ("team_id");

CREATE UNIQUE INDEX "stat_manager_assignments_uniq_match_user" ON public."stat_manager_assignments" ("match_id","user_id");

CREATE UNIQUE INDEX "team_season_roster_uniq_roster" ON public."team_season_roster" ("season_team_id","player_id");

CREATE INDEX "team_season_roster_player_id" ON public."team_season_roster" ("player_id");

CREATE INDEX "team_season_roster_season_team_id" ON public."team_season_roster" ("season_team_id");

CREATE UNIQUE INDEX "users_email" ON public."users" (LOWER("email"));

CREATE INDEX "wallet_transactions_user_id" ON public."wallet_transactions" ("user_id");

CREATE INDEX "withdrawal_requests_user_id" ON public."withdrawal_requests" ("user_id");

-- PostgreSQL indexes used by LeagueMN.
CREATE INDEX IF NOT EXISTS idx_mps_match ON public.match_player_stats (match_id);
CREATE INDEX IF NOT EXISTS idx_mps_player ON public.match_player_stats (player_id);
CREATE INDEX IF NOT EXISTS idx_mps_team ON public.match_player_stats (team_id);
CREATE INDEX IF NOT EXISTS idx_ms_user ON public.match_submit (user_id);
CREATE INDEX IF NOT EXISTS idx_ms_status ON public.match_submit (status);
CREATE INDEX IF NOT EXISTS idx_matches_datetime ON public.matches (match_datetime);
CREATE INDEX IF NOT EXISTS idx_matches_status ON public.matches (status);
CREATE INDEX IF NOT EXISTS idx_sma_user ON public.stat_manager_assignments (user_id);
CREATE INDEX IF NOT EXISTS idx_wt_user_id ON public.wallet_transactions (user_id, id);

REVOKE ALL ON TABLE public."leagues" FROM anon, authenticated;
REVOKE ALL ON TABLE public."matches" FROM anon, authenticated;
REVOKE ALL ON TABLE public."match_player_stats" FROM anon, authenticated;
REVOKE ALL ON TABLE public."match_status" FROM anon, authenticated;
REVOKE ALL ON TABLE public."match_submit" FROM anon, authenticated;
REVOKE ALL ON TABLE public."match_team_stats" FROM anon, authenticated;
REVOKE ALL ON TABLE public."news" FROM anon, authenticated;
REVOKE ALL ON TABLE public."players" FROM anon, authenticated;
REVOKE ALL ON TABLE public."seasons" FROM anon, authenticated;
REVOKE ALL ON TABLE public."season_teams" FROM anon, authenticated;
REVOKE ALL ON TABLE public."stat_manager_assignments" FROM anon, authenticated;
REVOKE ALL ON TABLE public."teams" FROM anon, authenticated;
REVOKE ALL ON TABLE public."team_season_roster" FROM anon, authenticated;
REVOKE ALL ON TABLE public."users" FROM anon, authenticated;
REVOKE ALL ON TABLE public."wallet_transactions" FROM anon, authenticated;
REVOKE ALL ON TABLE public."withdrawal_requests" FROM anon, authenticated;
